import { useEffect, useState } from 'react'

import { connect } from 'react-redux'
import swal from 'sweetalert2'
import { Row, Card, Select, Form, Button, notification, Col, Input, Icon } from 'antd'

import ClaimActions from '../../redux/claims/actions'
import errorActions from '../../../redux/error/actions'

import PermissionCheckerV2 from '../../../components/permissionCheckerV2'
import FileUploadOnGcsV2 from '../../../components/FileUploadOnGcsV2'

import fileUrls from '../../../request/urls/file'

import {
  Center,
  DetailDiv,
  InfoContainer,
  BulkStatusUpload,
  SearchBulkUploadContainer,
} from './claim.style'

const { Item } = Form
const { Option } = Select

const {
  updateBulkStatus,
  resetBulkStatusState,
  getBulkUploadNameFileInfo,
  resetReduxStateClaim,
} = ClaimActions

const {
  resetErrorRedux
} = errorActions

const actions = [
  {
    name: 'Default Status Update',
    code: 'default',
    permissionRequired: 'ops.view_default_option_bulk_status'
  },
  {
    name: 'Kredivo Payment Update',
    code: 'simas_payment_update',
    permissionRequired: 'ops.view_kredivo_option_bulk_status'
  }
]

function FileUploads(props) {
  const [actionValue, setActionValue] = useState('default')
  const [permissionActions, setPermissionsActions] = useState([])
  const [searchBulkUploadName, setSearchBulkUploadName] = useState('')
  const {
    form,
    profileData,
    getBulkUploadNameFileInfo,
    bulkFileUplaodInfoStatus,
    resetReduxStateClaim,
    bulkFileUplaodInfoData = {},
    bulkFileUploadLoading = false,
    bulkFileUploadInfoLoading = false
  } = props
  const { getFieldDecorator } = form

  const failedNotif = (message = 'An error occured in uploading the files. Please try again') => {
    notification.error({ message })
  }

  const handleSubmit = () => {
    form.validateFields((error, values) => {
      let fileUrl
      if (error) {
        return
      }
      if (values && values['bulk-status-file'] && values['bulk-status-file'].length !== 0) {
        const errorFiles = values['bulk-status-file'].filter((file) => file.error)

        if (errorFiles && errorFiles.length !== 0) {
          failedNotif()
          return
        }

        try {
          const fileObj = values['bulk-status-file'] && values['bulk-status-file'][0]
          const uploadedFile = fileObj.response?.data?.url
          fileUrl = uploadedFile.split('s3.ap-southeast-3.amazonaws.com')[1]
          const bucketName = uploadedFile.split('s3.ap-southeast-3.amazonaws.com')[0].split('//')[1].split('.')[0]
          fileUrl = decodeURI(bucketName + fileUrl)
        } catch (err) {
          failedNotif()
        }

        if (!fileUrl) {
          failedNotif()
          return
        }
        const body = {
          uploaded_file: `s3:/${fileUrl}`,
          provider: values['action-dropdown'],
          custom_name: values.custom_name
        }
        props.updateBulkStatus(body)
      }
    })
  }

  useEffect(() => {
    const status = props.bulkUploadStatus
    const { permissions } = props
    if (status === 'Error') {
      notification.error({
        message: props.bulkUploadMessage || 'An error occured in uploading the files. Please try again'
      })
      resetReduxStateClaim(['bulkUploadStatus', 'bulkUploadMessage'])
      props.resetErrorRedux(['bulkUploadStatus', 'bulkUploadMessage'])
    } else if (status === 'Success') {
      notification.success({ message: props.bulkUploadMessage ? `File Uploaded successfully. Batch Id: ${props.bulkUploadMessage}` : 'File Uploaded successfully' })
      form.resetFields()
      props.resetBulkStatusState()
      setActionValue('default')
    }

    const tempArr = []

    actions.forEach((item) => {
      if (Array.isArray(permissions) && permissions.includes(item.permissionRequired)) {
        tempArr.push(item)
      }
    })

    setPermissionsActions(tempArr)
  }, [props.bulkUploadStatus, form, props, props.bulkUploadMessage, resetReduxStateClaim])

  useEffect(() => {
    if (bulkFileUplaodInfoStatus === "Error") {
      if (bulkFileUplaodInfoStatus.isDownloading) {
        notification.error({
          message: bulkFileUplaodInfoData?.error || 'Not able to send bulk upload data contact tech team'
        })
      } else {
        notification.error({
          message: bulkFileUplaodInfoData?.error || bulkFileUplaodInfoStatus
        })
      }
      resetErrorRedux()
      resetReduxStateClaim(['bulkFileUplaodInfoMessage', 'bulkFileUplaodInfoStatus'])
    }
      if (bulkFileUplaodInfoStatus === 'Success') {
        if (bulkFileUplaodInfoData.isDownloading) {
          notification.success({
            message: 'Data is sent to the mail'
          })
        }
        resetErrorRedux()
        resetReduxStateClaim(['bulkFileUplaodInfoMessage', 'bulkFileUplaodInfoStatus'])
      }
    }, [bulkFileUplaodInfoStatus, bulkFileUplaodInfoData, resetReduxStateClaim, bulkFileUplaodInfoData.isDownloading])


  const onSearchBulkUploadNameChangeHandler = (event) => {
    const { value } = event.target
    setSearchBulkUploadName(value)
  }

  const onBulkUploadNameSearchHandler = () => {
    if (!searchBulkUploadName) {
      notification.error({
        message: 'Enter Bulk upload name'
      })
      return
    }
    getBulkUploadNameFileInfo({
      query: {
        custom_name: searchBulkUploadName
      }
    })
  }

  const onDownloadClickHandler = () => {
    swal({
      title: 'Report will send to your email ',
      input: 'email',
      inputValue: profileData.email,
      showCancelButton: true,
      confirmButtonText: 'Send',
      showLoaderOnConfirm: true,
      allowOutsideClick: () => false
    }).then(result => {
      if (result.dismiss !== 'cancel') {
        getBulkUploadNameFileInfo({
          query: {
            email: result.value,
            download_data: 1,
            custom_name: searchBulkUploadName
          }
        })
      }
    })
  }
  return (
    <>
      <BulkStatusUpload>
        <Card className='uploads-card'>
          <Row>
            <h3 className='upload-file-heading'>Bulk File Uploads</h3>
            {/* <Button
            type='primary'
            onClick={() => props.history.push('/claims/claim-management/file-uploads')}
          >
            <Icon type='excel' /> File Uploads <Icon type='caret-right' />
          </Button> */}
          </Row>
          <Form form={form} layout='inline' className='upload-form' name="upload-form">
            <Row type='flex'>
              <Item label='Action'>
                {getFieldDecorator('action-dropdown', {
                  initialValue: actionValue
                })(
                  <>
                    <Select
                      showSearch
                      dropdownMatchSelectWidth={false}
                      style={{ width: 200 }}
                      value={actionValue}
                      onChange={value => setActionValue(value)}
                      label='action-dropdown'
                    >

                      {permissionActions.map((action) => (
                        <Option key={action.code} value={action.code}>
                          {action.name}
                        </Option>
                      ))}
                    </Select>
                  </>
                )}
              </Item>

              <PermissionCheckerV2 requiredPermission='ops.claim_bulk_status_update'>
                <Col >
                  <Item>
                    <FileUploadOnGcsV2
                      signedUrlEndPoint={fileUrls.generateSignedURL}
                      getFieldDecorator={getFieldDecorator}
                      name='bulk-status-file'
                      identifier='claims'
                      minSize={0.00}
                      form={form}
                      maxFileAllowed={1}
                      buttonText='Choose File'
                      buttonClassName='fluid-width'
                      icon='cloud-upload'
                      required
                      maxSize={10}
                      onPreview={false}
                      accept='.csv'
                      formItemProps={{ label: 'Bulk Update Status' }}
                      fileNameLength={25}
                    />
                  </Item>
                </Col>
              </PermissionCheckerV2>

              <Item label="Bulk Upload Name">
                {
                  getFieldDecorator('custom_name', {
                    initialValue: '',
                    rules: [
                      { required: true, message: 'Bulk Upload name is required' }
                    ]
                  })(
                    <Input />
                  )
                }
              </Item>

              <Item>
                <Button
                  type='primary'
                  htmlType='button'
                  onClick={handleSubmit}
                  loading={bulkFileUploadLoading}
                >
                  Upload
                </Button>
              </Item>
            </Row>
          </Form>
        </Card>

        <Card>
          <SearchBulkUploadContainer>
            <div>
              <span>Bulk Upload Name:</span>
              <Input
                defaultValue=""
                value={searchBulkUploadName}
                onChange={onSearchBulkUploadNameChangeHandler}
                width="400px"
              />
            </div>
            <Center>
              <Button
                type='primary'
                loading={bulkFileUploadInfoLoading}
                onClick={onBulkUploadNameSearchHandler}>
                Search
              </Button>
            </Center>
          </SearchBulkUploadContainer>
          <div>
            {Object.keys(bulkFileUplaodInfoData).length && !(bulkFileUplaodInfoData.error) && (bulkFileUplaodInfoData.success)
              ?
              <>
                <InfoContainer>
                  <DetailDiv className='container'>
                    <div>Batch Id:</div><div>{bulkFileUplaodInfoData?.data?.batch_id ?? 'N/A'}</div>
                  </DetailDiv>
                  <DetailDiv className='container'>
                    <div>File Name:</div><div>{bulkFileUplaodInfoData?.data?.file_name ?? 'N/A'}</div>
                  </DetailDiv>
                  <DetailDiv className='container'>
                    <div>Uploaded On:</div><div>{bulkFileUplaodInfoData?.data?.uploaded_on ?? 'N/A'}</div>
                  </DetailDiv>
                  <DetailDiv className='container'>
                    <div>Successful Rows:</div><div>{bulkFileUplaodInfoData?.data?.successful_rows ?? 'N/A'}</div>
                  </DetailDiv>
                  <DetailDiv className='container'>
                    <div>Failed Rows:</div><div>{bulkFileUplaodInfoData?.data?.failed_rows ?? 'N/A'}</div>
                  </DetailDiv>
                  <DetailDiv className='container'>
                    <div>Unprocessed Rows:</div><div>{bulkFileUplaodInfoData?.data?.unprocessed_rows ?? 'N/A'}</div>
                  </DetailDiv>
                </InfoContainer>
                <Button onClick={onDownloadClickHandler}>
                  <Icon type='cloud-download' />
                  Download
                </Button>
              </>
              : null}
          </div>
        </Card>
      </BulkStatusUpload>
    </>
  )
}

const BulkFileUploads = Form.create()(FileUploads)

export default connect(
  (state) => ({
    permissions: state.Auth.permissions,
    bulkUploadStatus: state.Claims.bulkUploadStatus,
    bulkUploadMessage: state.Claims.bulkUploadMessage,
    bulkFileUplaodInfoStatus: state.Claims.bulkFileUplaodInfoStatus,
    bulkFileUplaodInfoData: state.Claims.bulkFileUplaodInfoData,
    profileData: state.Auth.profile,

    bulkFileUploadInfoLoading: state.Loading.GET_BULK_UPLOAD_NAME_FILE_INFO,
    bulkFileUploadLoading: state.Loading.BULK_STATUS_UPDATE
  }),
  {
    updateBulkStatus,
    resetBulkStatusState,
    getBulkUploadNameFileInfo,
    resetErrorRedux,
    resetReduxStateClaim,
  }
)(BulkFileUploads)
